-- [HOOKS] installed before the obfuscated script captures globals
do
    local LOG_PATH = "hook_trace.txt"
    local MAX_STR  = 800
    local _writefile  = rawget(_G, "writefile")
    local _appendfile = rawget(_G, "appendfile")
    local _readfile   = rawget(_G, "readfile")
    local _print      = rawget(_G, "print")

    -- Initialize / clear log file
    if type(_writefile) == "function" then
        pcall(_writefile, LOG_PATH, "")
    end

    local function safe_tostring(v)
        local ok, s = pcall(tostring, v)
        if not ok then return "<unstringable>" end
        if type(v) == "string" and #v > MAX_STR then
            return s:sub(1, MAX_STR) .. ("...(%d bytes total)"):format(#v)
        end
        return s
    end

    local _line_no = 0
    local function emit(line)
        _line_no = _line_no + 1
        local stamped = ("[%05d] %s"):format(_line_no, line)
        if type(_appendfile) == "function" then
            pcall(_appendfile, LOG_PATH, stamped .. "\n")
        elseif type(_writefile) == "function" then
            local existing = ""
            if type(_readfile) == "function" then
                local ok, data = pcall(_readfile, LOG_PATH)
                if ok and type(data) == "string" then existing = data end
            end
            pcall(_writefile, LOG_PATH, existing .. stamped .. "\n")
        end
        if type(_print) == "function" then
            _print(stamped)
        end
    end

    local function log(name, ...)
        local parts = {}
        for i = 1, select("#", ...) do
            parts[#parts + 1] = safe_tostring(select(i, ...))
        end
        emit("[hook] " .. tostring(name) .. " " .. table.concat(parts, " "))
    end

    -- ===== HTTP hooks =====
    local realRequest = rawget(_G, "request")
    rawset(_G, "request", function(opts)
        log("request", opts and opts.Method, opts and opts.Url, opts and opts.Body)
        if type(realRequest) == "function" then return realRequest(opts) end
        return { StatusCode = 404, Body = "" }
    end)

    local realHttpRequest = rawget(_G, "http_request")
    rawset(_G, "http_request", function(opts)
        log("http_request", opts and opts.Method, opts and opts.Url, opts and opts.Body)
        if type(realHttpRequest) == "function" then return realHttpRequest(opts) end
        return { StatusCode = 404, Body = "" }
    end)

    if type(syn) == "table" and type(syn.request) == "function" then
        local realSynRequest = syn.request
        syn.request = function(opts)
            log("syn.request", opts and opts.Method, opts and opts.Url, opts and opts.Body)
            return realSynRequest(opts)
        end
    end

    if type(http) == "table" and type(http.request) == "function" then
        local realHttpTableRequest = http.request
        http.request = function(opts)
            log("http.request", opts and opts.Method, opts and opts.Url, opts and opts.Body)
            return realHttpTableRequest(opts)
        end
    end

    -- ===== game hooks (HttpGet, GetService) =====
    local g = rawget(_G, "game")
    if g then
        pcall(function()
            local realHttpGet = g.HttpGet
            if type(realHttpGet) == "function" then
                g.HttpGet = function(self, url, ...)
                    log("game:HttpGet", tostring(url))
                    return realHttpGet(self, url, ...)
                end
            end
        end)
        pcall(function()
            local realGetService = g.GetService
            if type(realGetService) == "function" then
                g.GetService = function(self, name, ...)
                    log("game:GetService", tostring(name))
                    return realGetService(self, name, ...)
                end
            end
        end)
    end

    -- ===== loadstring =====
    local realLoadstring = rawget(_G, "loadstring")
    rawset(_G, "loadstring", function(src, chunkname)
        local s = type(src) == "string" and src or ""
        log("loadstring", "len=" .. #s, "chunk=" .. safe_tostring(chunkname), "preview=" .. s:sub(1, MAX_STR))
        if type(realLoadstring) == "function" then return realLoadstring(src, chunkname) end
        return nil, "no loadstring available"
    end)

    -- ===== file IO =====
    if type(_writefile) == "function" then
        rawset(_G, "writefile", function(path, data)
            log("writefile", path, safe_tostring(data))
            return _writefile(path, data)
        end)
    end
    if type(_readfile) == "function" then
        rawset(_G, "readfile", function(path)
            local ok, data = _readfile(path)
            log("readfile", path, "ok=" .. tostring(ok), "data=" .. safe_tostring(data))
            return ok, data
        end)
    end
    if type(_appendfile) == "function" then
        rawset(_G, "appendfile", function(path, data)
            log("appendfile", path, safe_tostring(data))
            return _appendfile(path, data)
        end)
    end

    -- ===== getgenv =====
    local realGetgenv = rawget(_G, "getgenv")
    if type(realGetgenv) == "function" then
        rawset(_G, "getgenv", function()
            log("getgenv")
            return realGetgenv()
        end)
    end

    emit("[hook] installation complete; logging to " .. LOG_PATH)
end

